-- =============================================================================
-- seed_organiser_events.sql
--
-- 8 organisers and 50 events, each with a full Information block, a line-up,
-- ticket tiers, a refund policy and terms. Built to exercise the phase 1-6
-- work end to end rather than just to fill a list.
--
-- WHAT IS DELIBERATELY VARIED
--
--   * Organiser 8 (Garden Route Escapes) sits at kyc_level 1. Their public
--     page MUST 404 and the organiser block MUST be absent from their four
--     events. That is the gate under test, not an oversight.
--   * Organiser 7 (Pretoria Business Network) has NO social links. Their page
--     must still look finished.
--   * Six events are free (price 0). Several are sold out or nearly so.
--   * Four events are in the past, so the organiser page's Past tab has
--     something in it.
--   * One event is published_private — it must NOT appear in any public list
--     or on an organiser page.
--   * Sports events use event_lineup rows of kind 'team'; music and arts use
--     'performer' with stages and set times.
--
-- REQUIRES: migrations up to 000082.
--
-- RUN:
--   docker compose exec -T db psql -U devuser -d events_dev < seed_organiser_events.sql
--
-- IDEMPOTENT: every insert is guarded. Safe to re-run.
--
-- REMOVE EVERYTHING THIS CREATED:
--   DELETE FROM events     WHERE id::text LIKE 'e5000000-%';
--   DELETE FROM organizers WHERE id::text LIKE 'a5000000-%';
--   DELETE FROM users      WHERE id::text LIKE 'd5000000-%';
--   (event_info_items, event_lineup and ticket_types cascade with the event.)
-- =============================================================================

BEGIN;

-- Slug helper. Matches the shape make_slug() produces in seed_sa_events.sql so
-- seeded events are indistinguishable from organically created ones.
CREATE OR REPLACE FUNCTION seed_slug(title TEXT, id UUID) RETURNS TEXT AS $fn$
  SELECT trim(BOTH '-' FROM regexp_replace(lower(title), '[^a-z0-9]+', '-', 'g'))
         || '-' || substr(id::text, 1, 8);
$fn$ LANGUAGE SQL IMMUTABLE;

