-- ── Line-ups ─────────────────────────────────────────────────────────────────
-- Sports events get kind='team' rows; music and arts get 'performer' with
-- stages and set times. set_time is a full timestamp anchored to the event's
-- own start_time, because festivals cross midnight and a bare clock time
-- would be ambiguous about the day.
INSERT INTO event_lineup (event_id, kind, name, image_url, subtitle, stage, set_time, external_url, sort_order)
SELECT v.event_id, v.kind, v.name, v.image_url, v.subtitle, v.stage,
       CASE WHEN v.set_hour IS NULL THEN NULL
            ELSE date_trunc('day', e.start_time) + (v.set_hour || ' hours')::interval END,
       v.external_url, v.sort_order
