WHERE NOT EXISTS (SELECT 1 FROM event_lineup l WHERE l.event_id = v.event_id);

-- Keep the legacy performers/teams arrays in step with event_lineup.
-- Shipped mobile builds read those columns directly, so a seeded event whose
-- arrays were empty would show no line-up on any phone that has not updated.
-- This is the same dual write ReplaceEventLineup performs.
UPDATE events e SET
  performers = COALESCE((SELECT array_agg(l.name ORDER BY l.sort_order)
                         FROM event_lineup l WHERE l.event_id = e.id AND l.kind = 'performer'), '{}'),
  teams      = COALESCE((SELECT array_agg(l.name ORDER BY l.sort_order)
                         FROM event_lineup l WHERE l.event_id = e.id AND l.kind = 'team'), '{}')
WHERE e.id::text LIKE 'e5000000-%';

