WHERE NOT EXISTS (SELECT 1 FROM ticket_types t WHERE t.event_id = v.event_id);

-- ── Announcement latches ─────────────────────────────────────────────────────
--
-- Seeded events are published with a line-up already attached, so they must be
-- marked as already-announced. Without this the phase 2 worker would treat all
-- 50 as newly published and the phase 6 worker would read every line-up as
-- newly added — anyone following a seeded organiser would get a notification
-- storm the first minute the API runs.
UPDATE events e
SET followers_notified_at = COALESCE(published_at, NOW()),
    lineup_notified_at    = NOW(),
    lineup_announced_snapshot = COALESCE(
      (SELECT jsonb_object_agg(kind, names) FROM (
         SELECT l.kind, jsonb_agg(l.name ORDER BY l.name) AS names
         FROM event_lineup l WHERE l.event_id = e.id GROUP BY l.kind) g),
      '{}'::jsonb)
WHERE e.id::text LIKE 'e5000000-%';

DROP FUNCTION IF EXISTS seed_slug(TEXT, UUID);

COMMIT;

-- ── Verify ───────────────────────────────────────────────────────────────────

SELECT o.business_name, o.slug, o.kyc_level, o.public_profile_enabled,
       count(e.id) FILTER (WHERE e.status = 'published')  AS live,
       count(e.id) FILTER (WHERE e.status = 'completed')  AS past,
       count(l.id)                                        AS link_count
FROM organizers o
LEFT JOIN events e ON e.organizer_id = o.user_id
LEFT JOIN organizer_links l ON l.organizer_id = o.id
WHERE o.id::text LIKE 'a5000000-%'
GROUP BY o.id, o.business_name, o.slug, o.kyc_level, o.public_profile_enabled
ORDER BY o.business_name;

SELECT c.name AS category, count(*) AS events,
       count(*) FILTER (WHERE e.price = 0) AS free,
       count(*) FILTER (WHERE e.tickets_sold >= e.max_capacity) AS sold_out
FROM events e JOIN categories c ON c.id = e.category_id
WHERE e.id::text LIKE 'e5000000-%'
GROUP BY c.name ORDER BY events DESC;

SELECT
  (SELECT count(*) FROM event_info_items i JOIN events e ON e.id = i.event_id
     WHERE e.id::text LIKE 'e5000000-%') AS info_items,
  (SELECT count(*) FROM event_lineup l JOIN events e ON e.id = l.event_id
     WHERE e.id::text LIKE 'e5000000-%') AS lineup_rows,
  (SELECT count(*) FROM ticket_types t JOIN events e ON e.id = t.event_id
     WHERE e.id::text LIKE 'e5000000-%') AS ticket_tiers,
  (SELECT count(*) FROM events WHERE id::text LIKE 'e5000000-%'
     AND followers_notified_at IS NULL) AS unannounced_must_be_zero;